<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import PageHeading from '../components/PageHeading.vue'
import UiIcon from '../components/UiIcon.vue'
import SourceChip from '../components/SourceChip.vue'
import ConfidenceBadge from '../components/ConfidenceBadge.vue'
import SegMeter from '../components/SegMeter.vue'
import SkeletonBlock from '../components/SkeletonBlock.vue'
import EmptyState from '../components/EmptyState.vue'
import StatusBanner from '../components/StatusBanner.vue'
import AchievementsSection from '../components/AchievementsSection.vue'
import AgentAvatar from '../components/AgentAvatar.vue'
import { demo } from '../store'
import { backendDemo } from '../lib/backend-demo'
import { skin } from '../lib/theme'
import { STUDENT, PROFILE_FIELDS, NOTICES } from '../data/student'
import { reminderRecords } from '../lib/reminder-records'
import InfoSheet from '../components/InfoSheet.vue'
const route=useRoute(), router=useRouter()
const key=computed(()=>String(route.name))
const titles:Record<string,string>={settings:'账号设置',reminders:'提醒',guide:'使用指南',gallery:'通用组件与状态',login:'登录',achievements:'成长记录'}
const descriptions:Record<string,string>={settings:'你在这里决定：它能读什么、什么时候可以找你，以及你的资料怎么保留。',reminders:'先看需要你处理的事。处理、暂时不安排和已读是不同的状态。',guide:'先把自己讲清楚，再比较方向，最后做一件今天完成得了的小事。',gallery:'同一套组件，在不同来源、把握度和状态下怎样呈现。这里的控制会改变真实显示状态。',login:'进入你的咨询记录。当前为演示环境，可以选择预置账号体验不同阶段。',achievements:'每条成长记录都能追到具体发生过的事。未解锁的记录也会说明还缺什么。'}
const account=ref('mid'), password=ref(''), error=ref(''), status=ref('')
const avatarState=ref<'idle'|'thinking'|'speaking'>('thinking'), sampleState=ref('content'), confidence=ref(0.8)
const reminderFilter=ref('all')
const reminderHistory=computed(()=>reminderRecords.items)
const preferences=ref({academic:true,materials:true,proactive:true,quietFrom:'22:00',quietTo:'08:00'})
try {const saved=localStorage.getItem('zhiyin-c2-preferences');if(saved)preferences.value={...preferences.value,...JSON.parse(saved)}}catch{/* Session defaults remain usable. */}
watch(preferences, value=>{try{localStorage.setItem('zhiyin-c2-preferences',JSON.stringify(value))}catch{status.value='本次选择已保留；当前浏览器没有允许保存到下次。'}},{deep:true})
watch(key,()=>{error.value='';status.value=''})
function login(){if(!password.value.trim()){error.value='请填写演示密码；任意非空字符即可。';return}demo.signIn(account.value);password.value='';router.push('/chat')}
function exportData(){const body=JSON.stringify({name:demo.state.account==='fresh'?'新用户':STUDENT.name,profile:backendDemo.state.liveWorkspace?.profile_panel??(demo.state.account==='fresh'?[]:PROFILE_FIELDS),notes:backendDemo.state.notes,report:backendDemo.state.liveReport,source:'本地演示导出'},null,2);const url=URL.createObjectURL(new Blob([body],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='职引-我的资料.json';link.click();URL.revokeObjectURL(url);status.value='已导出当前资料与来源。'}
function handleReminder(id:string,action:'read'|'later'|'done'|'restore'){const notice=demo.state.noticeQueue.find(n=>n.id===id)??reminderRecords.items.find(r=>r.id===id)?.original??NOTICES.find(n=>n.id===id);if(!notice)return;if(action==='restore'){demo.restoreNotice(notice);const index=reminderRecords.items.findIndex(r=>r.id===id);if(index>=0)reminderRecords.items.splice(index,1);status.value='已恢复到待处理，原来的行动与截止标记仍保留。';return}const result=action==='read'?'已读，尚未处理':action==='later'?'稍后再看':'已处理';const old=reminderRecords.items.findIndex(r=>r.id===id);const record={id:notice.id,title:notice.title,body:notice.body,result,state:action,original:{...notice},kind:notice.kind,at:new Date().toISOString(),until:action==='later'?new Date(Date.now()+86400000).toISOString():undefined};if(old>=0)reminderRecords.items.splice(old,1,record);else reminderRecords.items.unshift(record);if(action==='done'){demo.restoreNotice(notice);demo.resolveNotice(id);}else if(action==='later')demo.dismissNotice(id);status.value=action==='read'?'已标为已读，提醒仍待处理。':action==='later'?'已放入稍后记录；本地演示不创建服务端定时通知。':'已处理提醒，相关任务加入行动计划。'}
const reminderPool=computed(()=>[...demo.state.noticeQueue.map(n=>({id:n.id,title:n.title,body:n.body,kind:n.kind,deadline:n.deadline,action:n.action,secondary:n.secondary,state:'pending',result:'待处理',at:undefined as string|undefined,until:undefined as string|undefined})),...reminderHistory.value.filter(r=>r.state!=='read').map(r=>({...r,deadline:r.original?.deadline,action:r.original?.action??'',secondary:r.original?.secondary??'',state:r.state??'later'}))].map(r=>{const history=reminderHistory.value.find(h=>h.id===r.id&&h.state==='read');return history?{...r,state:'read',result:history.result,at:history.at}:r}))
const reminderGroups=computed(()=>{const groupOf=(r:typeof reminderPool.value[number])=>reminderFilter.value==='kind'?(r.kind??'提醒'):reminderFilter.value==='time'?(r.until?.slice(0,10)??r.at?.slice(0,10)??r.deadline??'时间未提供'):r.state==='later'?'已经放到稍后':r.state==='done'?'已经处理':r.deadline?'有截止标记，先核对':'仍需决定怎么处理';return [...new Set(reminderPool.value.map(groupOf))].map(title=>({title,items:reminderPool.value.filter(r=>groupOf(r)===title)}))})

const guideSteps=[{title:'先把自己讲清楚',detail:'在咨询中说出当前最困扰你的问题。学校资料、本人说明和顾问判断各自保留来源。',to:'/chat',action:'开始咨询'},{title:'核对它到底知道什么',detail:'在画像里换来源、时间与主题看；信息不对可以直接更正，缺口不替你补造。',to:'/profile',action:'核对个人画像'},{title:'三个方向放在一起比',detail:'比较同一批条件。调整你看重什么，看到排序怎样变，再由你确认选择。',to:'/directions',action:'比较方向'},{title:'今天先做一件小事',detail:'任务带着为什么是现在、补哪条差距和大约需要多久。做完留下记录，再来复盘。',to:'/home',action:'看今日行动'}]
const guideFaq=[{q:'系统会替我选择方向吗？',a:'不会。权重排序帮助比较，方向仍由你确认，确认后还可以更改。'},{q:'信息不对怎么办？',a:'在画像里点开那一条，核对原始依据后更正。受影响的判断会保留需要重算的提示。'},{q:'资料取不到怎么办？',a:'区分这次没取到、取了但没有、这条路取不到。资料不足的地方保留缺口，不补造数据。'},{q:'计划没完成就算失败吗？',a:'记录任务、方法或方向上的原因，再拆小一步。原因不归到人，已经发生的记录仍保留。'}]
const glossary=[{term:'个人画像',detail:'已经了解的信息、来源与缺口，不是给人的固定标签。'},{term:'诊断报告',detail:'由依据撑起来的判断，保留版本与不确定性。'},{term:'方向方案',detail:'用同一把尺子比较候选方向，再由你确认。'},{term:'阶段计划',detail:'有目标、时间窗和前后依赖的执行步骤。'},{term:'把握度',detail:'说明依据有多结实，信息不足不能当成确定判断。'},{term:'来源',detail:'原始资料从哪里来，以及什么时候取得。'},{term:'缺口',detail:'目前还缺的具体依据，可以补充或继续核对。'}]
const familyAxis=ref('purpose'), familyDialog=ref(false), sampleText=ref('')
const families=[{key:'button',title:'按钮与动作',purpose:'做操作',to:'/home'},{key:'field',title:'字段与表单',purpose:'做操作',to:'/settings'},{key:'tabs',title:'组织与切换',purpose:'读信息',to:'/profile'},{key:'source',title:'来源',purpose:'读信息',to:'/academic'},{key:'confidence',title:'把握度',purpose:'读信息',to:'/report'},{key:'meter',title:'进度',purpose:'读信息',to:'/plan'},{key:'table',title:'同刻度比较',purpose:'读信息',to:'/directions'},{key:'dialog',title:'对话框与抽屉',purpose:'做操作',to:'/notes'},{key:'loading',title:'加载',purpose:'讲状态',to:'/tools'},{key:'empty',title:'空白',purpose:'讲状态',to:'/notes'},{key:'error',title:'错误与恢复',purpose:'讲状态',to:'/notfound'},{key:'status',title:'状态与反馈',purpose:'讲状态',to:'/review'}]
const familyGroups=computed(()=>{const groupOf=(f:typeof families[number])=>familyAxis.value==='page'?f.to:f.purpose;return [...new Set(families.map(groupOf))].map(title=>({title,items:families.filter(f=>groupOf(f)===title)}))})
</script>
<template><div class="ws-page c2-system-page"><PageHeading :title="titles[key]??'学生空间'" :description="descriptions[key]??''"><RouterLink v-if="key==='guide'||key==='gallery'" class="btn" to="/chat">回到咨询<UiIcon name="arrow" :size="16"/></RouterLink><button v-if="key==='settings'" class="btn" @click="exportData">导出我的资料</button></PageHeading><StatusBanner v-if="error" tone="error" :message="error"/><StatusBanner :open="!!status" tone="success" :message="status" @dismiss="status=''"/>
<template v-if="key==='settings'"><div class="c2-system-layout"><main><section class="ws-paper"><h2>我的账号</h2><dl class="c2-key-values"><div><dt>姓名</dt><dd>{{ demo.state.account==='fresh'?'新用户':STUDENT.name }}</dd></div><div><dt>学校与专业</dt><dd>{{ demo.state.account === 'fresh' ? '学校与专业待补充' : STUDENT.school + ' · ' + STUDENT.major }}</dd></div><div><dt>当前数据</dt><dd>{{ backendDemo.state.dataMode==='demo'?'预置人物与本地演示记录':'读取服务端资料' }}</dd></div></dl></section><section class="ws-paper"><h2>学校资料与本人材料</h2><p>开关保存在本地演示设置中。正式资料的导入、核验与撤回在资料页完成。</p><label class="c2-setting-row"><span><strong>学校资料</strong><small>成绩与课程；不会替你读取未授权的资料</small></span><input v-model="preferences.academic" type="checkbox" role="switch"/></label><label class="c2-setting-row"><span><strong>本人上传的材料</strong><small>保留本人来源，不能自动成为已核验的学校记录</small></span><input v-model="preferences.materials" type="checkbox" role="switch"/></label><RouterLink class="btn" to="/academic">管理已导入的资料</RouterLink></section><section class="ws-paper"><h2>它什么时候可以找你</h2><label class="c2-setting-row"><span><strong>主动提醒</strong><small>{{ preferences.proactive?'保留任务节点与复盘提醒':'主动提醒已关闭；仍可手动查看现有提醒' }}</small></span><input v-model="preferences.proactive" type="checkbox" role="switch"/></label><div class="c2-quiet-hours"><label>安静时间，从<input v-model="preferences.quietFrom" type="time"/></label><label>到<input v-model="preferences.quietTo" type="time"/></label></div><p>本地演示偏好：{{ preferences.quietFrom }}–{{ preferences.quietTo }}。不会替服务端创建定时任务。</p></section><section class="ws-paper"><h2>外观</h2><p>也可以直接在顶栏切换。三个轴各自保存，不改变你的资料。</p><button class="btn" @click="skin.reset();status='已恢复默认外观。'">恢复默认外观</button></section><section class="ws-paper"><h2>导出与退出</h2><p>导出包含当前画像与个人记录。退出后回到门户，可再选择演示账号。</p><div class="ws-inline-actions"><button class="btn" @click="exportData">导出我的资料</button><button class="btn" @click="demo.signOut();router.push('/')">退出登录</button></div></section></main><aside><section class="ws-paper"><h2>哪些是本地设置</h2><p>外观与本页演示偏好存在当前浏览器。资料导入、更正和撤回使用各自的服务入口。</p><RouterLink class="ws-text-link" to="/academic">核对资料与授权 →</RouterLink></section><section class="ws-paper"><h2>你的组织权</h2><p>来源、时间、主题与对判断的贡献是四种不同的读法。更正资料后，旧报告仍保留原版，不会悄悄变成新结论。</p></section></aside></div></template>
<template v-else-if="key==='reminders'"><div class="c2-system-layout"><main><section class="c2-profile-stats"><article class="c2-profile-stat"><strong>{{ demo.state.noticeQueue.filter(n=>!reminderHistory.some(r=>r.id===n.id&&r.state==='read')).length }}</strong><small>条</small><h2>还没有读过</h2><p>已读与已经处理分别保留</p></article><article class="c2-profile-stat"><strong>{{ reminderPool.filter(r=>r.state==='later').length }}</strong><small>条</small><h2>放到稍后</h2><p>重新安排前仍保留内容</p></article></section><section class="ws-paper"><div class="c2-lensbar" role="group" aria-label="提醒的组织方式"><button v-for="o in [{key:'all',label:'按紧急程度'},{key:'kind',label:'按事项类型'},{key:'time',label:'按时间'}]" :key="o.key" :aria-pressed="reminderFilter===o.key" @click="reminderFilter=o.key">{{ o.label }}</button></div><section v-for="group in reminderGroups" :key="group.title" class="c2-note-group"><h3>{{ group.title }}<span>{{ group.items.length }} 条</span></h3><article v-for="notice in group.items" :key="notice.id" class="c2-reminder" :data-state="notice.state"><span>{{ notice.kind }} · {{ notice.result }}<template v-if="notice.deadline"> · {{ notice.deadline }}</template></span><h2>{{ notice.title }}</h2><p>{{ notice.body }}</p><p v-if="notice.until">稍后记录日期：{{ new Date(notice.until).toLocaleDateString('zh-CN') }}</p><div v-if="notice.state==='pending'||notice.state==='read'" class="ws-inline-actions"><button class="btn" @click="handleReminder(notice.id,'done')">{{ notice.action }}</button><button class="ws-text-button" @click="handleReminder(notice.id,'later')">稍后再看</button><button v-if="notice.state==='pending'" class="ws-text-button" @click="handleReminder(notice.id,'read')">标为已读</button></div><div v-else-if="notice.state==='later'" class="ws-inline-actions"><button class="btn" @click="handleReminder(notice.id,'done')">现在处理</button><button class="ws-text-button" @click="handleReminder(notice.id,'restore')">恢复到待处理</button></div><RouterLink v-else class="ws-text-link" to="/home">查看相关行动 →</RouterLink></article></section><EmptyState v-if="!reminderPool.length" kind="notes" title="还没有提醒记录" description="出现任务节点时，在这里保留处理过程。"/></section></main><aside><section class="ws-paper"><h2>三种处理方式</h2><p>已读只说明看过；稍后保留待安排的事项；处理会进入相关行动。记录不会因为换个组织方式而消失。</p><RouterLink class="ws-text-link" to="/settings">调整提醒设置 →</RouterLink></section></aside></div></template>
<template v-else-if="key==='guide'"><div class="c2-system-layout"><main><section class="ws-paper"><h2>这四步，前一步接着后一步</h2><ol class="c2-tool-chain"><li v-for="step in guideSteps" :key="step.to"><h3>{{ step.title }}</h3><p>{{ step.detail }}</p><RouterLink class="btn" :to="step.to">{{ step.action }}<UiIcon name="arrow" :size="16"/></RouterLink></li></ol></section><section class="ws-paper"><h2>信息没变，也可以换个看法</h2><p>同一批资料按来源、时间、主题与对判断的贡献重新组织。更换看法不会删除资料，每条的原文和把握度仍保留。</p><RouterLink class="ws-text-link" to="/profile">试着重组个人画像 →</RouterLink></section></main><aside><section class="ws-paper"><h2>你的选择仍由你做</h2><p>方向排序是比较，不是替你决定。建议可以加入计划；任务完成后再来核对结果。</p></section><section class="ws-paper"><h2>先核对来源</h2><p>演示岗位、课程与统计只用来说明交互。信息不足会明确保留，不补造一个确定结论。</p></section></aside></div></template>
<template v-if="key==='guide'"><section class="ws-paper"><h2>常见问题</h2><details v-for="faq in guideFaq" :key="faq.q" class="c2-faq"><summary>{{ faq.q }}</summary><p>{{ faq.a }}</p></details></section><section class="ws-paper"><h2>这几个词是什么意思</h2><dl class="c2-key-values"><div v-for="item in glossary" :key="item.term"><dt>{{ item.term }}</dt><dd>{{ item.detail }}</dd></div></dl></section></template>
<template v-if="key==='login'"><div class="c2-login-layout"><section class="ws-paper"><h2>继续你的这一段</h2><p>对话、画像、方向与行动放在一起，来源各自保留。</p><form class="c2-login-form" @submit.prevent="login"><label>演示账号<select v-model="account"><option value="mid">陈亦然 · 大三，已有报告与计划</option><option value="fresh">新用户 · 从零开始</option><option value="stale">已有记录 · 三天未推进</option></select></label><label>演示密码<input v-model="password" type="password" autocomplete="off" placeholder="任意非空字符" required/></label><p>本页使用本地演示账号，不收集真实账号密码。</p><button class="btn btn--primary" type="submit">登录，进入咨询<UiIcon name="arrow" :size="16"/></button></form></section><aside><h2>先聊清楚，再做选择</h2><p>公开门户不需要登录。进入演示账号后，可以核对资料、比较方向，再把建议变成今天做得到的小事。</p><RouterLink class="btn" to="/">先回门户看看</RouterLink></aside></div></template>
<template v-if="key==='achievements'"><AchievementsSection/></template>
<template v-if="key==='gallery'"><section class="ws-paper"><h2>12 类组件，放在同一套语言里</h2><p>换组织方式时同一批组件重新分组；每一族都能追到正在使用它的页面。</p><div class="c2-lensbar"><button :aria-pressed="familyAxis==='purpose'" @click="familyAxis='purpose'">按做什么看</button><button :aria-pressed="familyAxis==='page'" @click="familyAxis='page'">按在哪一页用</button></div><section v-for="group in familyGroups" :key="group.title" class="c2-note-group"><h3>{{ group.title }}<span>{{ group.items.length }} 类</span></h3><div class="c2-family-grid"><article v-for="family in group.items" :key="family.key" class="c2-family"><h3>{{ family.title }}</h3><input v-if="family.key==='field'" v-model="sampleText" placeholder="试着填写一条信息"/><div v-else-if="family.key==='button'" class="ws-inline-actions"><button class="btn" @click="status='这一次动作已完成。'">执行样例</button><button class="btn" disabled>不可用</button></div><button v-else-if="family.key==='dialog'" class="btn" @click="familyDialog=true">打开样例</button><SourceChip v-else-if="family.key==='source'" source="record"/><ConfidenceBadge v-else-if="family.key==='confidence'" :confidence="confidence"/><SegMeter v-else-if="family.key==='meter'" :total="5" :lit="3" label="五项中完成三项的样例"/><SkeletonBlock v-else-if="family.key==='loading'" variant="text" :lines="2"/><p v-else>{{ family.purpose }} · 用当前页面核对实际状态</p><RouterLink class="ws-text-link" :to="family.to">看使用它的页面 →</RouterLink></article></div></section></section><InfoSheet :open="familyDialog" title="对话框样例" @close="familyDialog=false"><p>这里承载需要单独核对的信息。关闭后回到原来的组件索引。</p><button class="btn" @click="familyDialog=false">完成并返回</button></InfoSheet><section class="ws-paper"><h2>顾问在场感</h2><div class="c2-gallery-presence"><AgentAvatar agent="career" :size="96" :state="avatarState"/><div><h3>职业分析顾问</h3><p>{{ avatarState==='thinking'?'正在想':avatarState==='speaking'?'正在说':'在听' }}</p><div class="c2-lensbar"><button v-for="state in ['idle','thinking','speaking'] as const" :key="state" :aria-pressed="avatarState===state" @click="avatarState=state">{{ state==='idle'?'待命':state==='thinking'?'思考':'说话' }}</button></div></div></div></section><section class="ws-paper"><h2>来源、把握度与进度是不同的读数</h2><div class="ws-inline-actions"><SourceChip source="record"/><SourceChip source="conversation"/><SourceChip source="user_edit"/><SourceChip source="assessment"/></div><label class="c2-confidence-control">调整把握度<input v-model.number="confidence" type="range" min="0" max="1" step="0.1"/></label><ConfidenceBadge :confidence="confidence"/><SegMeter :total="10" :lit="Math.round(confidence*10)" label="组件样例，十格进度"/></section><section class="ws-paper"><h2>内容、加载、空白与失败</h2><table class="c2-state-matrix"><caption>四个流程阶段的状态矩阵 · 点击切换下方样例</caption><thead><tr><th>流程</th><th v-for="state in [{key:'content',label:'有内容'},{key:'loading',label:'正在取'},{key:'empty',label:'取了但没有'},{key:'error',label:'没有取到'}]" :key="state.key">{{ state.label }}</th></tr></thead><tbody><tr v-for="flow in ['资料读取','任务保存','报告取得','消息输出']" :key="flow"><th>{{ flow }}</th><td v-for="state in ['content','loading','empty','error']" :key="state"><button :aria-pressed="sampleState===state" @click="sampleState=state">查看样例</button></td></tr></tbody></table><div class="c2-lensbar"><button v-for="state in [{key:'content',label:'有内容'},{key:'loading',label:'正在取'},{key:'empty',label:'取了但没有'},{key:'error',label:'没有取到'}]" :key="state.key" :aria-pressed="sampleState===state.key" @click="sampleState=state.key">{{ state.label }}</button></div><SkeletonBlock v-if="sampleState==='loading'" variant="list" :lines="3"/><EmptyState v-else-if="sampleState==='empty'" kind="notes" title="还没有记录" description="这是空态的样例，可以切回有内容。"/><StatusBanner v-else-if="sampleState==='error'" tone="error" message="这次没有取得资料；上一次记录仍保留。" retry-label="重试样例" @retry="sampleState='content'"/><p v-else>内容默认可见。刷新时保留原内容，等待与失败各自说明发生了什么。</p></section></template>
</div></template>
